#!/usr/bin/env bash
# Fill: TOTP code generated by the daemon and injected into a child.
# Usage: run_totp.sh <web-credential-label>
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$HERE/../common.sh"
label=$(cred_label "${1:-}")

response=$(agent-pwd fill --cred "$label" --field totp)
handle=$(printf '%s\n' "$response" | json_field handle)
agent-pwd fill apply --handle "$handle" -- python3 "$HERE/show_length.py"
